    this.router.events
      .pipe(filter(event => event instanceof NavigationEnd))
      .subscribe((event: NavigationEnd) => {
        this.updateActiveTab(event.url);
      });

    // Set initial active tab
    this.updateActiveTab(this.router.url);
  }

